mapper.insert:
INSERT INTO system_feedback (user_id, user_number, user_name, role, content, contact)
SELECT u.user_id, u.user_number, u.name, u.role, #{content}, #{contact}
FROM users u
WHERE u.user_number = #{userNumber}

mapper.select:
SELECT FROM system_feedback
AND status = #{status}
ORDER BY created_at DESC, feedback_id DESC

mapper.update:
UPDATE system_feedback
SET reply = #{reply}, status = 'resolved'
WHERE feedback_id = #{feedbackId}
